diff --git a/debian/changelog b/debian/changelog
index 73e9742..970bde4 100644
--- a/debian/changelog
+++ b/debian/changelog
@@ -1,3 +1,9 @@
+init-system-helpers (1.66ubuntu2.1) noble; urgency=high
+
+  * Fix deb-systemd-helper remove_links() infinite loop (LP: #2164744)
+
+ -- Hector Cao <hector.cao@canonical.com>  Sat, 22 Aug 2026 11:28:31 +0200
+
 init-system-helpers (1.66ubuntu2) noble; urgency=high

   * No change rebuild for 64-bit time_t and frame pointers.
diff --git a/script/deb-systemd-helper b/script/deb-systemd-helper
index 5e7e167..cef2e95 100755
--- a/script/deb-systemd-helper
+++ b/script/deb-systemd-helper
@@ -439,7 +439,7 @@ sub debian_installed {
 }

 sub remove_links {
-    my ($service_path) = @_;
+    my ($service_path, @visited) = @_;

     my $dsh_state = dsh_state_path($service_path);
     my @entries = state_file_entries($dsh_state);
@@ -480,12 +480,23 @@ sub remove_links {
     # dh_installsystemd generating an appropriate disable
     # command by parsing the service file at debhelper-time.
     open(my $fh, '<', "$dpkg_root$service_path") or return;
+    my $unit_name = basename($service_path);
+    push @visited, $unit_name;
     while (my $line = <$fh>) {
         chomp($line);
         my $service_link;

         if ($line =~ /^\s*Also=(.+)$/i) {
-            remove_links(find_unit($1));
+            # Also= can contain multiple unit names, separated by whitespace. See
+            # systemd.unit(5) for details.
+            for my $value (split(/\s+/, $1)) {
+                $value =~ s/^(["'])(.*)\g1$/$2/;
+                # We can end up in an infinite recursion, so remember what units we
+                # already processed to break it
+                next if grep $_ eq $value, @visited;
+                push @visited, $value;
+                remove_links(find_unit($value), @visited);
+            }
         }
     }
     close($fh);
